#include <sys/socket.h>
#include <arpa/inet.h>

typedef enum {
    DEBUG,
    INFO,
    WARN,
    ERROR,
    CRITICAL
} LogLevel;

struct Logger {
    pthread_mutex_t lock;
    time_t last_log[NUM_LOG_LEVELS];
    // Other fields for metrics and external logging service
};

void log(LogLevel level, const char *message) {
    struct Logger *logger = get_logger(); // Get instance of the Logger object
    pthread_mutex_lock(&logger->lock);
    if (time(NULL) - logger->last_log[level] > MAX_TIME_WINDOW) { // Duplicate detection
        fprintf(stderr, "[%s] %s\n", level_to_string(level), message);
        logger->last_log[level] = time(NULL);
    }
    pthread_mutex_unlock(&logger->lock);
}

void configure_logging(const char *service_url, int max_retries, long backoff_ms) {
    // Initialize and configure the external logging service
}
```

