// Custom Semaphore struct to store additional metadata and manage IPC
struct semaphore {
    // Semaphore value (count)
    int count;

    // POSIX shared memory segment ID
    key_t shmid;

    // Shared memory segment size
    size_t size;

    // Pointer to the shared memory segment
    void* addr;

    // Mutex for thread safety
    pthread_mutex_t lock;
};

