using Newtonsoft.Json;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace ConfigurationService
{
    public class ConfigurationManager : IHostedService, IDisposable
    {
        private readonly HttpClient _httpClient;
        private readonly IConfiguration _configuration;
        private readonly ILogger<ConfigurationManager> _logger;
        private readonly PerformanceMonitor _performanceMonitor;

        public ConfigurationManager(HttpClient httpClient, IConfiguration configuration, ILogger<ConfigurationManager> logger, PerformanceMonitor performanceMonitor)
        {
            _httpClient = httpClient;
            _configuration = configuration;
            _logger = logger;
            _performanceMonitor = performanceMonitor;
        }

        public async Task StartAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Starting ConfigurationManager");
            LoadConfiguration();
            ConfigureResources();
            SubscribeToPerformanceMetrics();
        }

        private void LoadConfiguration()
        {
            var configUrl = _configuration["ConfigUrl"];
            using (var response = await _httpClient.GetAsync(configUrl, HttpCompletionOption.ResponseHeadersRead))
            {
                if (!response.IsSuccessStatusCode)
                    throw new Exception($"Failed to load configuration: {response.StatusCode}");

                var json = await response.Content.ReadAsStringAsync();
                var config = JsonConvert.DeserializeObject<Config>(json);
                DecryptConfiguration(config);
            }
        }

        private void DecryptConfiguration(Config config)
        {
            using (var aes = Aes.Create())
            {
                var key = Encoding.UTF8.GetBytes(_configuration["EncryptionKey"]);
                using (var decryptor = new AesCryptoServiceProvider() { Key = key })
                    config.Decrypt(decryptor.CreateDecryptor());
            }
        }

        private void ConfigureResources()
        {
            // Adjust resource allocation based on current load and predefined thresholds
            // ...
        }

        private void SubscribeToPerformanceMetrics()
        {
            _performanceMonitor.OnMetricChanged += HandleMetricChange;
        }

        private void HandleMetricChange(string metricName, double value)
        {
            if (value > _configuration["Tolerance"])
                TriggerAlert($"{metricName} exceeded tolerance: {value}");
        }

        private void TriggerAlert(string message)
        {
            // Send alert to external monitoring service
            // ...
        }

        public async Task StopAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Stopping ConfigurationManager");
        }

        public void Dispose()
        {
            _httpClient.Dispose();
        }
    }
}
```

