import reactor.core.publisher.Mono;

@RestController
@RequestMapping("/api/profiles")
public class UserProfileController {

    @Autowired
    private UserProfileRepository userProfileRepository;

    @GetMapping("/{id}")
    public Mono<UserProfile> getUserProfileById(@PathVariable Long id) {
        return userProfileRepository.findById(id);
    }

    @PostMapping
    @PreAuthorize("hasRole('ADMIN')")
    public Mono<UserProfile> createUserProfile(@RequestBody UserProfile userProfile) {
        // Implement validation and versioning mechanisms here
        return userProfileRepository.save(userProfile);
    }

    @PutMapping("/{id}")
    @PreAuthorize("hasRole('USER')")
    public Mono<ResponseEntity<?>> updateUserProfile(@PathVariable Long id, @RequestBody UserProfile updatedUserProfile) {
        return userProfileRepository.findById(id)
                .flatMap(userProfile -> {
                    if (updatedUserProfile.getId() != null && !updatedUserProfile.getId().equals(userProfile.getId())) {
                        // Handle unauthorized update attempts here
                        return Mono.just(new ResponseEntity<>(HttpStatus.FORBIDDEN));
                    }
                    userProfile.updateFrom(updatedUserProfile);
                    return userProfileRepository.save(userProfile)
                            .then(Mono.just(new ResponseEntity<>(updatedUserProfile, HttpStatus.OK)));
                })
                .defaultIfEmpty(new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }

    // Define deleteUserProfile() method here
}
