['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include <json-c/json.h>

typedef struct ResourceBundle {
    size_t item_count;
    json_object *items;
    pthread_mutex_t mutex;
} ResourceBundle;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    ((char*)userp) += realsize;
    return realsize;
}

static ResourceBundle* create_resource_bundle() {
    ResourceBundle *rb = malloc(sizeof(ResourceBundle));
    if (!rb) {
        fprintf(stderr, "Error: Failed to allocate memory for ResourceBundle.\n");
        return NULL;
    }

    rb->item_count = 0;
    rb->items = json_object_new_array();
    pthread_mutex_init(&rb->mutex, NULL);
    return rb;
}

static int parse_resource_bundle(ResourceBundle *rb, const char *data) {
    json_object *root = json_tokener_parse(data);
    if (IS_ERR(root)) {
        fprintf(stderr, "Error: Failed to parse JSON data from remote server.\n");
        return -1;
    }

    size_t len = json_object_array_length(root);
    if (len > 0) {
        rb->item_count += len;
        rb->items = json_object_get(root);
    }

    json_object_put(root);
    return 0;
}

static void* fetch_and_process_bundle(void *arg) {
    CURL *curl;
    ResourceBundle *rb = arg;

    curl_global_init(CURL_GLOBAL_DEFAULT, 0);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: Failed to initialize cURL.\n");
        return NULL;
    }

    char *data = NULL;
    size_t data_size = 0;

    curl_easy_setopt(curl, CURLOPT_URL, "<YOUR_API_ENDPOINT>");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data);
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, NULL);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: Fetching resource bundle from remote server failed with error %d.\n", res);
        return NULL;
    }

    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
    if (res != HTTP_OK) {
        fprintf(stderr, "Error: Fetching resource bundle from remote server returned non-200 status code %d.\n", res);
        return NULL;
    }

    data[data_size] = '\0';
    int parse_result = parse_resource_bundle(rb, data);
    if (parse_result < 0) {
        return NULL;
    }

    free(data);
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return rb;
}

static int load_resource_bundle(ResourceBundle **rb, const char *api_endpoint) {
    if (!rb || !api_endpoint) {
        fprintf(stderr, "Error: Invalid arguments.\n");
        return -1;
    }

    pthread_t threads[MAX_THREADS];
    size_t num_threads = sysconf(_SC_NPROCESSORS_CONF);
    if (num_threads > MAX_THREADS) {
        num_threads = MAX_THREADS;
    }

    *rb = create_resource_bundle();
    if (!*rb) {
        return -1;
    }

    ResourceBundle *bundles[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        bundles[i] = *rb;
        pthread_create(&threads[i], NULL, fetch_and_process_bundle, bundles[i]);
    }

    ResourceBundle *merged_bundle = NULL;
    size_t total_items = 0;

    for (size_t i = 0; i < num_threads; ++i) {
        ResourceBundle *rb2 = NULL;
        pthread_join(threads[i], (void**)&rb2);

        if (rb2) {
            int merge_result = merge_bundles(*rb, rb2);
            if (merge_result < 0) {
                fprintf(stderr, "Error: Merging resource bundles failed.\n");
                continue;
            }
            total_items += rb2->item_count;
        }

        json_object_put(rb2->items);
        free(rb2);
    }

    merged_bundle = *rb;
    free(*rb);
    *rb = merged_bundle;

    return total_items > 0 ? total_items : -1;
}

static int merge_bundles(ResourceBundle *dest, ResourceBundle *src) {
    if (!dest || !src) {
        fprintf(stderr, "Error: Invalid arguments.\n");
        return -1;
    }

    pthread_mutex_lock(&dest->mutex);

    json_object *items = json_object_get(src->items);
    size_t len = json_object_array_length(items);

    for (size_t i = 0; i < len; ++i) {
        int result = append_item(dest, json_object_get(items, i));
        if (result < 0) {
            pthread_mutex_unlock(&dest->mutex);
            return -1;
        }
    }

    dest->item_count += src->item_count;
    pthread_mutex_unlock(&dest->mutex);
    return 0;
}

static int append_item(ResourceBundle *rb, json_object *item) {
    if (!rb || !item) {
        fprintf(stderr, "Error: Invalid arguments.\n");
        return -1;
    }

    pthread_mutex_lock(&rb->mutex);

    int result = json_object_array_append(rb->items, item);
    if (result < 0) {
        pthread_mutex_unlock(&rb->mutex);
        return -1;
    }

    rb->item_count++;
    pthread_mutex_unlock(&rb->mutex);
    return 0;
}
```

This code provides a basic structure for loading and processing a large resource bundle from a remote server. It uses the libcurl library for network requests, json-c library for parsing JSON data, and pthread for concurrent access to the resource bundle by multiple threads. You'll need to replace `<YOUR_API_ENDPOINT>` with your actual API endpoint URL.

Unit tests, documentation, and optimization should be added according to project requirements.']

