impl HttpClient {
    pub async fn new(config: Config) -> Self {
        let client = reqwest::Client::builder()
            .timeout(config.timeout)
            .cert(config.certificate_verifier)
            .build()
            .unwrap();
        Self { config, client }
    }

    // Other HTTP methods implementation (e.g., GET, POST, PUT, DELETE)
}

impl HttpRequest for reqwest::Request {
    async fn execute(&self, client: &HttpClient) -> Result<reqwest::Response, HttpError> {
        let token = match self.token_requirement() {
            TokenRequirement::Required => {
                if let Some(refresh_strategy) = &self.refresh_strategy {
                    match refresh_strategy {
                        TokenRefreshStrategy::Always => client
                            .config
                            .token_manager
                            .refresh(self)
                            .await?,
                        TokenRefreshStrategy::OnExpiry => {
                            // Check if the token has expired and refresh it if necessary
                        }
                    }
                } else {
                    return Err(HttpError::MissingTokenManager);
                }
            }
            TokenRequirement::Optional => {}
        };

        let mut req = self.clone();
        if !token.is_empty() {
            req.headers_mut().insert(
                HeaderName::from_static("Authorization"),
                HeaderValue::from_str(&format!("Bearer {}", token)).unwrap(),
            );
        }

        client.client.execute(req).await
    }
}
```

