CREATE PROCEDURE [dbo].[GetEmployeesBySupervisorAndCity]
    @SupervisorID INT,
    @PreferredCities VARCHAR(MAX) AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @employeeDetails TABLE (
        EmployeeID INT PRIMARY KEY IDENTITY(1,1),
        Name NVARCHAR(50),
        City NVARCHAR(50),
        Address NVARCHAR(255)
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO @employeeDetails (Name, City, Address)
        SELECT E.Name, E.City, E.Address
        FROM Employees AS E
        INNER JOIN Supervisors AS S ON E.SupervisorID = @SupervisorID
