int UserManager::updateUserPassword(int userId, const std::string& newPassword) {
    if (!policy.validate(newPassword))
        return -1; // General error: password does not meet requirements

    int statusCode = 0;

    // Queue the password update request with a lock to ensure concurrent updates are handled efficiently
    std::lock_guard<std::mutex> lock(queue_mutex);
    passwordUpdateQueue.emplace_back(userId, newPassword);

    while (!passwordUpdateQueue.empty()) {
        auto [userID, newPass] = passwordUpdateQueue.front();
        passwordUpdateQueue.pop();

        try {
            // Attempt to update the user's password in the database
