Now let's create a helper function to manage API rate limits and retries:

```python
import time
from functools import lru_cache

@lru_cache(maxsize=None, typed=True)
def rate_limited_call(func):
    def wrapper(*args, **kwargs):
        elapsed = 0
        while elapsed < func.__rate_limit__:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if isinstance(e, requests.exceptions.RequestException):
                    if func.__retries__ > 0:
                        func.__retries__ -= 1
                        time.sleep(func.__rate_limit__)
                        continue
                    else:
                        raise e
                else:
                    raise e
            elapsed += 1
    wrapper.__rate_limit__ = func.rate_limit
    wrapper.__retries__ = func.retries
    return wrapper
```

