    double activity_threshold;
    bool expand; // prune or expand
    int last_state;
    pthread_mutex_t mutex;
    time_t timeout;
} FSAManager;

FSAManager* create_fsa_manager(int *states, int size, FSA *fsa, int last_state, double activity_threshold, bool expand) {
    FSAManager *mgr = malloc(sizeof(FSAManager));
    mgr->states = states;
    mgr->size = size;
    mgr->current_state = last_state;
    mgr->fsa = fsa;
    mgr->activity_threshold = activity_threshold;
    mgr->expand = expand;
    mgr->last_state = last_state;
    pthread_mutex_init(&mgr->mutex, NULL);
    mgr->timeout = time(NULL) + 5; // 5 seconds timeout for fetching external activity metrics
    return mgr;
}

void destroy_fsa_manager(FSAManager *mgr) {
    free(mgr);
}

int* manage_fsa(FSAManager *mgr) {
    if (!mgr) return NULL;

    while (true) {
        pthread_mutex_lock(&mgr->mutex);
        time_t now = time(NULL);
        if ((now - mgr->timeout) > 0) { // timeout exceeded, handle error and continue
            printf("Error: Failed to fetch activity metrics for state %d within the timeout limit.\n", mgr->current_state);
            pthread_mutex_unlock(&mgr->mutex);
            continue;
        }
        int *updated_states = update_states(mgr); // update states using external data sources

        if (updated_states) { // handle potential failure from update_states
            if (updated_states != mgr->states) { // dynamic allocation, free old memory and allocate new one
                free(mgr->states);
                mgr->states = updated_states;
                mgr->size = mgr->states[0];
            }
            int i;
            for (i = 1; i <= mgr->size; ++i) { // handle edge cases, such as empty state lists or FSA with incomplete transitions
                if (!mgr->states[i]) {
                    printf("Error: State %d is not defined in the given FSA.\n", i);
                    free(updated_states);
                    pthread_mutex_unlock(&mgr->mutex);
                    return NULL;
                }
            }
            mgr->current_state = find_next_state(mgr); // decide which state to transition to next
        }

        if (mgr->current_state == -1) { // pruning condition, all states have been pruned
            pthread_mutex_unlock(&mgr->mutex);
            break;
        }

        pthread_mutex_unlock(&mgr->mutex);
    }

    int *pruned_or_expanded = (mgr->expand) ? expand_states(mgr) : prune_states(mgr); // handle expansion or pruning based on user input

    if (pruned_or_expanded && !memcmp(pruned_or_expanded, mgr->states, sizeof(int) * (mgr->size + 1))) { // no changes made
        free(pruned_or_expanded);
        return mgr->states;
    }

    if (!pruned_or_expanded) { // insufficient memory error
        printf("Error: Insufficient memory to expand/prune the state list.\n");
        return NULL;
    }

    free(mgr->states);
    mgr->states = pruned_or_expanded;
    return mgr->states;
}
```

