std::atomic<bool> g_running(true);
std::mutex g_tasks_mutex;
std::queue<nlohmann::json> g_tasks;
std::unordered_map<size_t, std::thread::id> g_task_threads;
size_t g_concurrency = 1;
std::atomic<int> g_retries(3);

struct ApiResponse {
    int status_code;
    nlohmann::json data;
};

void submit_task(const nlohmann::json& task) {
    std::lock_guard<std::mutex> lock(g_tasks_mutex);
    g_tasks.push(task);
}

ApiResponse call_api(const nlohmann::json& request) {
    CURL *curl;
    ApiResponse response;

    curl = curl_easy_init();
    if (!curl) {
        std::cerr << "Failed to initialize curl" << std::endl;
        response.status_code = -1;
        return response;
    }

    curl_easy_setopt(curl, CURLOPT_URL, request["api_url"].get<std::string>().c_str());
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, request.dump().c_str());
    curl_easy_setopt(CURLOPT_WRITEFUNCTION, [](void *ptr, size_t size, size_t nmemb, void *) {
        auto response = static_cast<std::string*>(ptr);
        const char *data = static_cast<const char*>(memccpy(&response[0], (char*)content, size*nmemb, size));
        if (!data) {
            response.append((char*)content, size*nmemb);
        } else {
            response.append(data, size*nmemb);
        }
    });

    CURLcode res;
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        std::cerr << "Failed to call API: " << curl_easy_strerror(res) << std::endl;
        response.status_code = -1;
    } else {
        response.status_code = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
        nlohmann::json json_response;
        if (json.parse(response.data)) {
            response.data = json_response;
        }
    }

    curl_easy_cleanup(curl);
    return response;
}

void worker() {
    while (g_running) {
        std::lock_guard<std::mutex> lock(g_tasks_mutex);
        if (!g_tasks.empty()) {
            auto task = g_tasks.front();
            size_t id = std::this_thread::get_id();
            g_task_threads[task["id"].get<size_t>()] = std::this_thread::get_id();
            g_tasks.pop();

            ApiResponse response;
            if (task["priority"] == "urgent") {
                // Prioritize urgent tasks
                response = call_api(task);
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(task["delay"].get<int>()));
                response = call_api(task);
            }

            if (response.status_code != -1) {
                // Log task execution status, error details, and resource utilization metrics here
            } else {
                if (--g_retries == 0) {
                    // Task failed permanently
                } else {
                    // Retry the task
                }
            }

            g_task_threads.erase(task["id"].get<size_t>());
        }
    }
}

int main() {
    boost::asio::io_context ioc;
    // WebSocket connection setup goes here

    std::vector<std::thread> worker_threads(g_concurrency);

    signal(SIGUSR1, [](int) {
        if (--g_concurrency > 0) {
            return;
        }
        g_running = false;
    });

    while (g_running) {
        ioc.run_one();
    }

    // Join worker threads and cleanup resources here

    int success = (g_task_threads.empty() && g_retries > 0) ? 1 : 0;
    if (success == -2) {
        std::cerr << "Resource constraints prevent accepting new tasks." << std::endl;
    }
    return success;
}
