    public class Deserializer
    {
        private readonly byte[] _aesKey = Encoding.UTF8.GetBytes("YOUR_AES_KEY");
        private readonly byte[] _hmacKey = Encoding.UTF8.GetBytes("YOUR_HMAC_KEY");

        public async Task<DataModel> DeserializeAsync(Stream dataStream)
        {
            using var aesAlg = Aes.Create();
            using var hmac = new HMACSHA256(_hmacKey);
            using var cipherStream = new CryptoStream(dataStream, aesAlg.CreateDecryptor(), CryptoStreamMode.Read);

            byte[] cipherText;
            await using (var ms = new MemoryStream())
            {
                cipherText = await cipherStream.ToArrayAsync();
                ms.Write(cipherText, 0, cipherText.Length);
                await ms.FlushAsync();
                var authenticationTag = aesAlg.Tag;

                if (!VerifySignature(hmac, ms))
                    throw new Exception("Invalid signature");

                var encryptedData = JsonConvert.DeserializeObject<EncryptedData>(Encoding.UTF8.GetString(ms.ToArray()));

                if (encryptedData.Version.Major > Constants.MaxSupportedVersion.Major ||
                    encryptedData.Version.Minor > Constants.MaxSupportedVersion.Minor)
                    throw new Exception("Unsupported schema version");
            }

            using var ms = new MemoryStream(encryptedData.CipherText);
            var deserializedObject = JsonConvert.DeserializeObject<DataModel>(DecodeBase64(DecodeAesGcm(aesAlg, ms)));

            return deserializedObject;
        }

        private string DecodeAesGcm(Aes aes, Stream stream)
        {
            var decryptedBytes = new AesCryptoServiceProvider() { Key = aes.Key, IV = aes.IV }.Decrypt(stream);
            return Encoding.UTF8.GetString(decryptedBytes);
        }

        private string DecodeBase64(byte[] input)
        {
            // Implement base64 decoding here
        }

        private bool VerifySignature(HMACSHA256 hmac, Stream stream)
        {
            var calculation = hmac.ComputeHash(stream);
            return Encoding.UTF8.GetString(calculation).Equals(encryptedData.Signature);
        }
    }
}
