['```java
package com.example.serialization;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInput;
import java.io.ObjectOutput;
import java.lang.reflect.InvocationTargetException;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public final class DeserializerUtil {
    private static final ConcurrentMap<String, Class<?>> CLASS_MAP = new ConcurrentHashMap<>();
    private static final ExecutorService VALIDATOR_POOL = Executors.newFixedThreadPool(10);
    private static final long VALIDATION_TIMEOUT_MS = 500L;

    public static <T> T deserialize(byte[] data, boolean lazyLoad, String schemaURL) throws IOException, ClassNotFoundException {
        Class<?> clazz = CLASS_MAP.computeIfAbsent(schemaURL, DeserializerUtil::getClassFromUrl);
        ObjectInput in = new ObjectInputStream(new ByteArrayInputStream(data));
        try {
            T object = (T) in.readObject();
            if (lazyLoad) {
                configureLazyLoading(object, clazz);
            }
            return object;
        } catch (ClassCastException e) {
            throw new SerializationException("Deserialized object does not match the specified class", e);
        } finally {
            in.close();
        }
    }

    private static Class<?> getClassFromUrl(String className) throws ClassNotFoundException {
        URL url = new URL(className);
        return Class.forName(url.getPath());
    }

    private static void configureLazyLoading(Object object, Class<?> clazz) {
        LazyLoader.configure(object, clazz);
    }

    public static void validate(Object obj, String schemaURL) {
        Runnable task = () -> SchemaValidator.validate(obj, getClassFromUrl(schemaURL));
        VALIDATOR_POOL.submit(task);
        try {
