#ifndef DYNAMIC_LIST_H
#define DYNAMIC_LIST_H

#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct Event {
    time_t timestamp;
    enum EventType { NETWORK_EVENT, SYSTEM_EVENT } event_type;
    uint64_t session_id;
    uint64_t ue_context;
} Event;

typedef struct Node {
    Event data;
    struct Node *next;
} Node;

typedef struct DynamicList {
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
    time_t retention_policy;
    void (*log_func)(const char* message);
} DynamicList;

DynamicList* dynamic_list_create(time_t retention_policy, void (*log_func)(const char* message));
void dynamic_list_add(DynamicList* list, const Event* event);
void dynamic_list_remove_expired(DynamicList* list);
Event* dynamic_list_get_most_recent_for_session(DynamicList* list, uint64_t session_id);

#endif // DYNAMIC_LIST_H
```

  2. C Library (dynamic_list.c)

```c
#include "dynamic_list.h"
#include <stdio.h>
#include <time.h>
#include <string.h>

static inline void log(const char* message) {
    if (dynamic_list->log_func != NULL)
        dynamic_list->log_func(message);
}

DynamicList* dynamic_list_create(time_t retention_policy, void (*log_func)(const char* message)) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) {
        log("Failed to allocate memory for dynamic list");
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->retention_policy = retention_policy;
    list->log_func = log_func;
    list->head = NULL;
    list->tail = NULL;

    return list;
}

void dynamic_list_add(DynamicList* list, const Event* event) {
    pthread_mutex_lock(&list->mutex);

    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        log("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    memcpy(&new_node->data, event, sizeof(Event));
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->mutex);
}

void dynamic_list_remove_expired(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *temp;

    while (current != NULL) {
        time_t current_time = time(NULL);
        if ((current_time - current->data.timestamp) > list->retention_policy) {
            temp = current->next;
            free(current);
            current = temp;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

Event* dynamic_list_get_most_recent_for_session(DynamicList* list, uint64_t session_id) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    Event* result = NULL;

    while (current != NULL) {
        if (current->data.session_id == session_id) {
            result = &current->data;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return result;
}
```

