function validateData($data, $rules = []) {
    $errors = [];

    foreach ($data as $key => $value) {
        if (!array_key_exists($key, $rules)) continue;

        $rule_parts = explode(':', $rules[$key]);
        $rule = array_shift($rule_parts);

        switch ($rule) {
            case 'required':
                if (empty($value)) $errors[] = "Field {$key} is required";
                break;
            case 'string':
                if (!is_string($value)) $errors[] = "Field {$key} must be a string";
                break;
            case 'email':
                if (!filter_var($value, FILTER_VALIDATE_EMAIL)) $errors[] = "Field {$key} is not a valid email address";
                break;
            case 'min':
                $min = intval(array_shift($rule_parts));
                if (strlen($value) < $min) $errors[] = "Field {$key} must be at least {$min} characters long";
                break;
        }
    }

    return empty($errors) ? '' : implode(", ", $errors);
}
