public class DynamicDisjointPairsAnalyzer {
    private static final Logger LOGGER = LoggerFactory.getLogger(DynamicDisjointPairsAnalyzer.class);
    private static final int TIERED_LOGGING_THRESHOLD = 1;
    private static final Cache<Integer, String> apiCache = CacheBuilder
            .newBuilder()
            .maximumSize(1000)
            .expireAfterWrite(Duration.create(3, TimeUnit.HOURS))
            .removalListener(new RemovalListener<Integer, String>() {
                @Override
                public void onRemoval(RemovalNotification<Integer, String> notification) {
                    LOGGER.debug("API cache eviction: {}", notification.getKey());
                }
            })
            .build();

    private static final ExecutorService executor = Executors.newCachedThreadPool(r -> {
        ThreadFactory namedThreadFactory = Executors.newThreadFactoryNamed("DynamicDisjointPairsAnalyzer-pool-%d");
        return namedThreadFactory.newThread(runnable);
    });

    private static final Future<?> garbageCollectorTask = new ScheduledExecutorService(() -> executor)
            .scheduleAtFixedRate(() -> {
                System.gc();
                Runtime.getRuntime().runFinalization();
                LOGGER.info("Manual garbage collection triggered");
            }, 5, 10, TimeUnit.SECONDS);

    public static void main(String[] args) throws Exception {
        AzureFunction.configureTelemetry(LOGGER);
        IgniteConfiguration igniteConfig = new IgniteConfiguration();
        // Configure distributed garbage collector and other settings as needed
        CacheConfiguration<Integer, String> cacheConfig = new CacheConfiguration<>();
        cacheConfig.setCacheMode(CacheMode.PARTITIONED);
        igniteConfig.setCacheConfiguration(cacheConfig);
        Ignition.start(igniteConfig);

        int targetDuration = Integer.parseInt(System.getenv().getOrDefault("TARGET_DURATION", "60")); // Configurable via environment variable

        List<Integer[]> arraysToProcess = Arrays.asList(
                new Integer[]{1, 2, 3, 4, 5, 6},
                new Integer[]{7, 8, 9, 10, 11, 12}
        );

        for (Integer[] array : arraysToProcess) {
            DisjointPairsAnalyzer analyzer = new DisjointPairsAnalyzer(targetDuration);
            int[] processedArray = analyzer.processArray(array).toArray();
            LOGGER.info("Disjoint pairs for [{}]: {}", Arrays.toString(array), Arrays.toString(processedArray));
        }

        Ignition.close();
    }

    private static class DisjointPairsAnalyzer {
        private final int targetDuration;
        private final UnionFind unionFind;
        private final ApiContext apiContext;

        public DisjointPairsAnalyzer(int targetDuration) {
            this.targetDuration = targetDuration;
            this.unionFind = new OptimizedUnionFind(); // Implement your custom Union-Find data structure here
            this.apiContext = new ApiContext();
        }

        public List<Integer> processArray(List<Integer> array) {
            List<Integer> processedArray = Lists.newArrayListWithCapacity(array.size());
            Runnable arrayProcessorTask = () -> {
                for (int i = 0; i < array.size(); i++) {
                    int index = i;
                    String contextData = fetchContextDataIfNeeded(index);
                    if (contextData != null) {
                        unionFind.union(index, contextData.hashCode());
                    }
                }

                for (int i = 0; i < array.size(); i++) {
                    int index = i;
                    processedArray.add(unionFind.find(index));
                }
            };

            executor.submit(arrayProcessorTask);
            try {
                arrayProcessorTask.get(targetDuration, TimeUnit.MILLISECONDS);
            } catch (TimeoutException e) {
                LOGGER.error("Processing of array took longer than the allowed time: {}", e.getMessage());
            } catch (ExecutionException e) {
                LOGGER.error("Error during processing of array: {}", e.getCause().getMessage());
            }

            return processedArray;
        }

        private String fetchContextDataIfNeeded(int index) {
            // Implement API integration, caching, and error handling here
            Integer cachedValue = apiCache.getIfPresent(index);
            if (cachedValue != null) {
                return cachedValue;
            }

            try {
                String contextData = apiContext.fetchContextData(index);
                apiCache.put(index, contextData);
                return contextData;
            } catch (Exception e) {
                LOGGER.error("Error while fetching context data for index {}", index, e);
                // Implement fallback mechanisms here
            }

            return null;
        }
    }

    private static class ApiContext {
