#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <json-c/json.h>
#include <curl/curl.h>

// Memory pool implementation
typedef struct MemPool {
    void* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MemPool;

MemPool* mempool_create(size_t initial_capacity) {
    MemPool* pool = malloc(sizeof(MemPool));
    if (!pool) return NULL;
    pool->data = malloc(initial_capacity);
    if (!pool->data) goto error;
    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    return pool;

error:
    free(pool);
    return NULL;
}

void* mempool_alloc(MemPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size + size <= pool->capacity) {
        void* data = pool->data + pool->size;
        pool->size += size;
        pthread_mutex_unlock(&pool->lock);
        return data;
    }
    pthread_mutex_unlock(&pool->lock);

    // Resize the memory pool and allocate the requested data.
    void* new_data = realloc(pool->data, pool->capacity * 2);
    if (!new_data) goto error;
    pool->data = new_data;
    pool->capacity *= 2;
    pthread_mutex_lock(&pool->lock);
    void* data = pool->data + pool->size;
    pool->size += size;
    pthread_mutex_unlock(&pool->lock);
    return data;

error:
    // Handle error and free resources.
    free(pool->data);
    free(pool);
    return NULL;
}

void mempool_free(MemPool* pool) {
    free(pool->data);
    free(pool);
}

// Implementation of the resolveHostname function and related infrastructure
