```csharp
private static int RetryOperation(Func<int> operation)
{
    Random random = new Random();
    int currentRetry = 1;
    while (currentRetry <= maxRetries)
    {
        try
        {
            return operation();
        }
        catch (Exception ex)
        {
            // Log error and increment retry count.
            currentRetry++;
            if (currentRetry < maxRetries)
                Thread.Sleep(random.Next(2 ^ (currentRetry - 1), 2 ^ currentRetry));
        }
    }

    // Handle max retries reached case.
}
```

