  const start = Date.now();
  const reqMetrics = new RequestMetrics({
    userId: req.user.id, // Assume user is authenticated and has an id
    requestId: req.uuid, // Generate a unique request ID for logging purposes
    method: req.method,
    url: req.url,
    timestamp: Date.now(),
  });

  reqMetrics.save().then(() => {
    next();
  }).catch((err) => {
    console.error(err);
    res.status(500).json({ error: 'Failed to log request metrics' });
  });

  const end = () => {
    const duration = Date.now() - start;
    const logEntry = new Log({
      userId: req.user.id, // Assume user is authenticated and has an id
      requestId: req.uuid, // Generate a unique request ID for logging purposes
      statusCode: res.statusCode || 0,
      duration: duration,
      timestamp: Date.now(),
    });

    logEntry.save().catch((err) => {
      console.error(err);
    });
  };

  req.on('finish', end); // End request logging on response finish event
});

