```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class NetworkEventNotificationManager
{
    private readonly ILogger<NetworkEventNotificationManager> _logger;
    private readonly TimeSpan _retentionPolicy;
    private readonly IExternalLoggingService _externalLoggingService;
    private readonly IUEContextProvider _ueContextProvider;
    private readonly IDictionary<string, NetworkEventList> _networkEvents;
    private readonly SemaphoreSlim _concurrencyControl = new SemaphoreSlim(10);

    public NetworkEventNotificationManager(IConfiguration configuration, IExternalLoggingService externalLoggingService, IUEContextProvider ueContextProvider)
    {
        _logger = configuration.GetService<ILogger<NetworkEventNotificationManager>>();
        _retentionPolicy = TimeSpan.FromMinutes(configuration["RetentionPolicy:Minutes"]);
        _externalLoggingService = externalLoggingService;
        _ueContextProvider = ueContextProvider;
        _networkEvents = new ConcurrentDictionary<string, NetworkEventList>();
    }

    public void AddEvent(NetworkEvent @event)
    {
        _concurrencyControl.Wait();
        try
        {
            if (_networkEvents.TryAdd(@event.SessionId, new NetworkEventList()))
                _logger.LogInformation("Added event: {Timestamp}, {EventType}, {SessionId}", @event.Timestamp, @event.EventType, @event.SessionId);
        }
        finally
        {
            _concurrencyControl.Release();
        }
    }

    public void RemoveExpiredEvents()
    {
        var expirationThreshold = DateTimeOffset.UtcNow - _retentionPolicy;
        _concurrencyControl.Wait();
        try
        {
            var eventsToRemove = _networkEvents.Where(x => x.Value.Timestamps.Any(t => t < expirationThreshold)).ToList();
            foreach (var eventGroup in eventsToRemove)
                _networkEvents.TryRemove(eventGroup.Key, out _);
        }
        finally
        {
            _concurrencyControl.Release();
        }
    }

    public NetworkEvent GetLatestEvent(string sessionId)
    {
        if (_networkEvents.TryGetValue(sessionId, out var networkEventList))
            return networkEventList.Timestamps.OrderByDescending(t => t).FirstOrDefault()?.ToNetworkEvent();

        return null;
    }
}
```

