// Globally shared dynamic list of event notifications
static GList* events;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for concurrent access

EventNotification* add_event(const char* session_id, const int event_type, const char* ue_context) {
    EventNotification *new_event = malloc(sizeof(EventNotification));
    new_event->timestamp = time(NULL);
    new_event->event_type = event_type;
    strncpy(new_event->session_id, session_id, MAX_SESSION_ID_LEN);
    strncpy(new_event->ue_context, ue_context, MAX_UE_CONTEXT_LEN);

    pthread_mutex_lock(&lock);
    events = g_list_append(events, new_event);
    pthread_mutex_unlock(&lock);

    return new_event;
}

void remove_expired_events() {
    // Implement retention policy and event removal here.
    ...
}

EventNotification* get_most_recent_event(const char* session_id) {
    EventNotification *result = NULL;

    pthread_mutex_lock(&lock);
    GList *current = events;

    while (current != NULL) {
        if (strcmp(session_id, ((EventNotification*)current->data)->session_id) == 0) {
            result = (EventNotification*)g_list_last(current)->prev;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return result;
}
