@Service
@HystrixCommand(commandKey = "processFile", fallbackMethod = "fallbackProcess")
public class DefaultFileProcessor implements FileProcessor {
    private final OktaAuthService oktaAuthService;
    private final FileSystemManager fileSystemManager;
    private final ThreadPoolExecutor threadPool;
    private final int maxBatchSize;
    private final int concurrencyLimit;

    public DefaultFileProcessor(OktaAuthService oktaAuthService, FileSystemManager fileSystemManager, ThreadPoolExecutor threadPool, @Value("${file-processor.max-batch-size}") int maxBatchSize, @Value("${file-processor.concurrency-limit}") int concurrencyLimit) {
        this.oktaAuthService = oktaAuthService;
        this.fileSystemManager = fileSystemManager;
        this.threadPool = threadPool;
        this.maxBatchSize = maxBatchSize;
        this.concurrencyLimit = concurrencyLimit;
    }

    @Override
    public void process(String fileName, String newFileName, String callbackUrl) throws Exception {
        // Validate input parameters

        // Authenticate user

        // Verify callback URL and safe extension format

        // Process file asynchronously using thread pool
        Runnable task = () -> {
            fileSystemManager.rename(fileName, newFileName);
            OkHttpClient client = new OkHttpClient();
            Request request = new Request.Builder().url(callbackUrl).build();
            client.newCall(request).execute();
        };
        threadPool.submit(task);
    }

    public void fallbackProcess(String fileName, String newFileName, String callbackUrl) {
        // Log partial failure and send email notification
    }
}
```

In this implementation:

