            {
                // Create IIS application pool and website using provided applicationPoolIdentity and siteName
                await InitializeWebsiteAsync(directory);
            }
            catch (Exception ex)
            {
                // Handle exceptions and retry within the specified number of retries with exponential backoff
                if (_maxRetries > 0 && ShouldRetry(ex))
