["1. C# Network Event Notification Component:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using NodaTime;
using Newtonsoft.Json;

public class NetworkEventNotificationService
{
    private readonly ILogger<NetworkEventNotificationService> _logger;
    private readonly IConfiguration _config;
    private readonly RetentionPolicy _retentionPolicy;
    private readonly Lazy<IExternalLoggingSystem> _loggingSystem;
    private readonly Lazy<IPdfConverter> _pdfConverter;

    public NetworkEventNotificationService(ILogger<NetworkEventNotificationService> logger, IConfiguration config, IOptionsMonitor<RetentionPolicy> retentionPolicy, IFactory<IExternalLoggingSystem> loggingSystemFactory, IFactory<IPdfConverter> pdfConverterFactory)
    {
        _logger = logger;
        _config = config;
        _retentionPolicy = retentionPolicy.CurrentValue;
        _loggingSystem = new Lazy<IExternalLoggingSystem>(loggingSystemFactory.Create);
        _pdfConverter = new Lazy<IPdfConverter>(pdfConverterFactory.Create);
    }

    public void AddEvent(NetworkEvent notification)
    {
        Lock.Acquire(_lock);
        try
        {
            _events.Add(notification);
            CleanExpiredEvents();
        }
        finally
        {
            Lock.Release();
        }

        _loggingSystem.Value.LogEventAdded(notification);
    }

    public NetworkEvent GetLatestEventForSession(Guid sessionId)
    {
        Lock.Acquire(_lock);
        try
        {
            return _events
                .Where(e => e.SessionId == sessionId)
                .OrderByDescending(e => e.Timestamp)
                .FirstOrDefault();
        }
        finally
        {
            Lock.Release();
        }
    }

    public async Task ExportEventsToPdfAsync()
    {
        var events = _events.ToList();
        var pdfData = await _pdfConverter.Value.ConvertEventsToPdf(events);
        // Store or send the PDF data to the desired destination
    }

    private void CleanExpiredEvents()
    {
        var expirationCutoffUtc = Instant.FromDateTime(_retentionPolicy.TimeSpan).Plus(_retentionPolicy.GracePeriod);
        var eventsToRemove = _events
            .Where(e => e.Timestamp < expirationCutoffUtc)
            .ToList();

        if (eventsToRemove.Any())
        {
            Lock.Acquire(_lock);
            try
            {
                foreach (var eventToRemove in eventsToRemove)
                {
                    _events.Remove(eventToRemove);
                }
                CleanExpiredEvents(); // Recursive call to handle concurrent expirations
            }
            finally
            {
                Lock.Release();
            }

            _loggingSystem.Value.LogCleanedExpiredEvents(eventsToRemove);
        }
    }

    private readonly List<NetworkEvent> _events = new();
    private readonly object _lock = new();
}
```

