};

static thread_local_storage_t* tls = NULL;

str_pool_t* str_pool_create(size_t cache_size) {
    if (cache_size == 0) return NULL;

    size_t total_size = sizeof(char) * cache_size + sizeof(struct str_pool_t);
    void* mem = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) return NULL;

    str_pool_t* pool = (str_pool_t*) mem;
    pool->length = cache_size;
    pool->pool = (char*) ((char*) pool + sizeof(struct str_pool_t));

    sem_init(&cache_sem, 0, cache_size);
    this->cache_size = cache_size;
    return pool;
}

void str_pool_destroy(str_pool_t* pool) {
    if (pool == NULL) return;

    munmap((void*) pool, sizeof(char) * pool->length + sizeof(struct str_pool_t));
}

char* str_pool_get(str_pool_t* pool, size_t length) {
    char* result = NULL;

    sem_wait(&cache_sem);
    if (cache_size > 0) {
        result = pool->pool;
        pool->pool += length + 1;
        cache_size--;
    } else {
        result = malloc(length + 1);
        if (result == NULL) goto err;
    }

    result[length] = '\0';
    return result;
err:
    sem_post(&cache_sem);
    return NULL;
}

void str_pool_put(str_pool_t* pool, char* str) {
    if (str == NULL || pool->length <= 0) return;

    sem_wait(&cache_sem);
    if (cache_size < pool->length) {
        memmove((char*) pool + sizeof(struct str_pool_t), str, strlen(str) + 1);
        pool->pool -= strlen(str) + 1;
        pool->length += strlen(str) + 1;
        cache_size++;
    } else {
        free(str);
    }
    sem_post(&cache_sem);
}

// Implement the rest of the functions for thread-local storage, logging, caching strategy, rate limiting, etc.
```

