}

public class SQLServerEventProcessor : BaseEventProcessor
{
    public SQLServerEventProcessor(IServiceProvider serviceProvider, IEventBus eventBus, RedisCache redisCache) : base(serviceProvider, eventBus, redisCache) { }

    [Inject]
    public IDbContextFactory<ApplicationDbContext> _dbContextFactory { get; set; }

    public override void ProcessEvent(IEvent @event)
    {
        using (var dbContext = _dbContextFactory.CreateDbContext())
        {
            // Transform and validate the event data here.
            var transformedData = TransformAndValidate(@event);

            // Perform batch processing if needed.
            _eventBus.Publish(new BatchEvent { Events = new List<IEvent> { @event } });

            // Save data to SQL Server using the dbContext.
            dbContext.SaveData(transformedData);
            dbContext.SaveChanges();
        }
    }
}
