#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <log.h> // External logging module implementation.

char* allocate_and_copy_string_with_suffix(const char *str, const char *suffix) {
    size_t len = strlen(str) + strlen(suffix);
    if (len > MAX_ALLOCATION_SIZE) {
        log_error("Allocation failure: String exceeds size limit.");
        return NULL;
    }

    pthread_mutex_lock(&allocation_mutex);
    char *allocated = malloc(len + 1);
    if (allocated == NULL) {
        log_error("Allocation failure: Could not allocate memory.");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    strcpy(allocated, str);
    strcat(allocated, suffix);
    pthread_mutex_unlock(&allocation_mutex);

    // Log the allocation for future reference.
    log_info("Allocation success: %s", allocated);

    return allocated;
}
