// ...

public class RateLimiter : IRateLimiter
{
    private readonly IMemoryCache _cache;
    private const int RequestInterval = 60;

    public RateLimiter(IMemoryCache cache)
    {
        _cache = cache;
    }

    public bool CanRequest()
    {
        return _cache.GetOrCreate("request_count") != null && (DateTimeOffset.UtcNow - (DateTimeOffset)_cache["request_count"]).TotalSeconds > RequestInterval;
