const { v4: uuidv4 } = require('uuid');

// Initialize Redis client and queue instance
const redisClient = redis.createClient();
const queueProcessor = new queue(process.env.QUEUE_NAME, { connection: redisClient });

// Initialize Express app
const app = express();
app.use(express.json());

// Define validation schema for metadata
const metadataSchema = Joi.object().keys({
  // Add your validation rules here
});

// Expose /process endpoint
app.post('/process', async (req, res) => {
  try {
    const { url, transformations, metadata } = req.body;

    // Validate input
    const { error } = metadataSchema.validate(metadata);
    if (error) return res.status(400).send({ message: error.message });

    // Cache or enqueue the task
    let taskId = req.query.cache || uuidv4();
    const cached = await redisClient.get(taskId);
    if (cached) {
      return res.send(JSON.parse(cached));
    } else {
      queueProcessor.createJob({ url, transformations, metadata }, { delay: 5000 }) // Adjust delay based on your backoff strategy
        .on('added', () => console.log(`Job enqueued with ID: ${taskId}`))
        .on('failed', (job) => handleJobFailure(job));
      res.send({ taskId });
    }
  } catch (error) {
    console.error(error);
    res.status(500).send({ message: 'An error occurred' });
  }
});

// Define a function to handle job failures
