  serviceB.call(() => handleValidationResult(null, obj), onError);
}

// Handle validation results and errors
function handleValidationResult(err, result) {
  if (err || !result.valid) {
    const errorMessage = err ? err.message : 'File is invalid';
    console.error(`${filePath}: ${errorMessage}`);
    // Add logging and notifications here for critical issues
  } else {
