// Third-party library for database connectivity (replace with actual implementation)
#include "DatabaseConnectivityLibrary.h"

namespace bip = boost::interprocess;

class UpdateClinicStatus {
public:
    UpdateClinicStatus(DatabaseConnectivityLibrary& dbLib);

    void updateClinicStatus(const ClinicID& clinicId, const Status& newStatus);

private:
    DatabaseConnectivityLibrary& dbLib_;
    std::mutex mtx_;
    bip::managed_shared_memory segment_;
    bip::vector<ClinicStatusUpdate> updates_;

    void processUpdates();
};

UpdateClinicStatus::UpdateClinicStatus(DatabaseConnectivityLibrary& dbLib) : dbLib_(dbLib), segment_(create_name, sizeof(ClinicStatusUpdate), bip::read_write) {
    updates_.set_allocator(bip::allocator_type(&segment_));
    std::thread processThread([this]() { processUpdates(); });
    processThread.detach();
}

void UpdateClinicStatus::updateClinicStatus(const ClinicID& clinicId, const Status& newStatus) {
    auto update = new (updates_.allocate()) ClinicStatusUpdate{clinicId, newStatus};
    updates_.push_back(update);
    mtx_.lock();
    updaterReady_.notify_one();
    mtx_.unlock();
}

void UpdateClinicStatus::processUpdates() {
    std::unique_ptr<ClinicStatusUpdate> update;
    while (true) {
        {
            std::unique_lock<std::mutex> lk(mtx_);
            updaterReady_.wait(lk, [this](){ return !updates_.empty(); });
            if (updates_.empty()) {
                break;
            }
            update.reset(&updates_.front());
            updates_.pop_front();
        }

        dbLib_.updateClinicStatus(update->clinicId, update->status);
    }
}
```

This implementation uses a producer-consumer pattern with a managed shared memory segment to hold the ClinicStatusUpdate objects. The `processUpdates()` function is responsible for handling database updates asynchronously and efficiently. It leverages Boost.Asio for non-blocking I/O operations, and Boost.Interprocess for managing shared memory. This design allows for concurrent access while ensuring thread safety using a mutex. The third-party library for database connectivity is injected through the constructor.']

