#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <time.h>

// External logging service interface (abstract)
typedef void (*LogFunc)(const char*, const int);

// Third-party memory pool manager interface (abstract)
typedef void* (*MemAlloc)(size_t);
typedef void (*MemFree)(void*);

// Custom memory allocator (optional)
static MemAlloc custom_memalloc = NULL;
static MemFree custom_memfree = NULL;

// Global variables for configuration and back-off strategy
const int MAX_ALLOCATIONS = 10000;
const int LOGGING_THRESHOLD = 100; // Log every N allocations
int num_allocations = 0;
sem_t log_mutex;
pthread_mutex_t mem_mutex;
struct timespec backoff_interval;

// Function to copy a string with suffix if within size limit
void* string_copy(const char *input, const char *suffix) {
    int len = strlen(input) + strlen(suffix);
    if (len > SIZE_LIMIT) return NULL; // Error: String exceeds size limit

    void *new_str = custom_memalloc ? custom_memalloc(len) : malloc(len);
    if (!new_str) return NULL; // Error: Memory allocation failed

    memcpy(new_str, input, strlen(input));
    strcat((char *)new_str, suffix);

    // Asynchronous logging with back-off strategy
    pthread_mutex_lock(&log_mutex);
    if (++num_allocations % LOGGING_THRESHOLD == 0) {
        log("String copy allocation at ", num_allocations, NULL);
        sem_post(&log_mutex);
    } else {
        sem_wait(&log_mutex);
        backoff(); // Back-off strategy if logging is busy
        log("String copy allocation at ", num_allocations, NULL);
        sem_post(&log_mutex);
    }
    pthread_mutex_unlock(&log_mutex);

    return new_str;
}

// Logging function for external service and test mock
void log(const char *message, const int extra_data, void *userdata) {
    static LogFunc real_log = NULL; // Replace with the actual logging function
    static LogFunc mock_log = NULL; // For testing purposes

    if (!real_log && mock_log) real_log = mock_log; // Set up for testing

    if (real_log) real_log(message, extra_data, userdata);
}

// Back-off strategy function
void backoff() {
    clock_gettime(CLOCK_MONOTONIC, &backoff_interval);
    backoff_interval.tv_sec += 10 * (backoff_interval.tv_nsec / 1_000_000_000);
    backoff_interval.tv_nsec = (backoff_interval.tv_sec % 1) * 1_000_000_000;
    usleep(backoff_interval.tv_sec * 1_000_000 + backoff_interval.tv_nsec);
}

// Initialize global variables and set up memory pool manager if necessary
void init() {
    sem_init(&log_mutex, 0, 1);
    pthread_mutex_init(&mem_mutex, NULL);

    // Load custom memory allocator and free functions if provided
    custom_memalloc = getenv("CUSTOM_MEMALLOC") ? (MemAlloc)dlsym(RTLD_DEFAULT, getenv("CUSTOM_MEMALLOC")) : NULL;
    custom_memfree = getenv("CUSTOM_MEMFREE") ? (MemFree)dlsym(RTLD_DEFAULT, getenv("CUSTOM_MEMFREE")) : NULL;
}
```

