class Module {
  constructor(name, dependencies = []) {
    this.name = name;
    this.dependencies = dependencies;
    this.state = 'idle'; // idle, loading, executed, error
  }

  async load() {
    if (this.state !== 'idle') return;
    this.state = 'loading';

    try {
      const moduleContent = await fetchModule(this.name);
      this.content = moduleContent;
      this.state = 'executed';
    } catch (error) {
      console.error(`Error loading module ${this.name}:`, error);
      this.state = 'error';
    }
  }

