["1. Configuration Service (using Node.js, Express, Mongoose, Redis, Axios):

```javascript
const express = require('express');
const mongoose = require('mongoose');
const redis = require('redis');
const axios = require('axios');
const crypto = require('crypto');

// Database schema for ConfigurationItem
const { Schema } = mongoose;
const configSchema = new Schema({
  key: { type: String, required: true },
  value: { type: String, required: true },
});
const Configuration = mongoose.model('Configuration', configSchema);

// Redis client
const redisClient = redis.createClient();

// Express app setup and route for fetching configuration items
const app = express();
app.use(express.json());

app.get('/config/:key', async (req, res) => {
  try {
    const configItem = await Configuration.findOne({ key: req.params.key });
    if (!configItem) return res.status(404).send();

    // Cache configuration item for TTL seconds in Redis
    redisClient.setex(`config_${req.params.key}`, configItem.value, (err) => {
      if (err) throw err;
    });

    res.json(configItem.value);
  } catch (error) {
    console.error(error);
    res.status(500).send();
  }
});

// External source fetching function
async function fetchData(url, retryCount = 3, backoff = 1000) {
  let response;
  try {
    response = await axios.get(url);
  } catch (error) {
    if (retryCount > 0) {
      await new Promise((resolve) => setTimeout(resolve, backoff));
      response = await fetchData(url, retryCount - 1, backoff * 2);
    } else {
      throw error;
    }
  }
  return response.data;
}

// Start the server on a specified port
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Configuration service listening on port ${PORT}`));
```

2. JavaScript function for extracting book names from Old Testament text:

```javascript
function getBookFrequencies(text) {
  const books = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
    'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings',
    '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job',
    'Psalms', 'Proverbs', 'Ecclesiastes', 'Song of Solomon', 'Isaiah',
    'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel',
    'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah',
    'Haggai', 'Zechariah', 'Malachi'];

  const regex = new RegExp(`\\b(${books.join('|')})\\b`, 'gi');
  const matches = text.match(regex);
  if (!matches) return {};

  const frequencies = {};
  for (const match of matches) {
    frequencies[match] = (frequencies[match] || 0) + 1;
  }
  return frequencies;
}
```"]

