    const char* inputs[] = {"hello", "world", "from", "the", "multi-threaded", "string", "copy", "function"};

    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_create(&workers[i], NULL, worker, inputs[i % ARRAY_SIZE(inputs)]);
