# Rust function to return exit code of a subprocess running the Rust compiler with custom logging hook

use std::env;
use std::fs;
use std::io::{self, Write};
use std::process::{Command, Stdio};
use sync_lazy::SyncLazy;
use log::{LevelFilter, SetLoggerError};
use error::Error;

fn compile(src: &str) -> i32 {
    let mut logger = setup_logger();
    let mut command = Command::new("rustc");
    command.stdin(Stdio::pipes().as_raw_fd());
    command.arg(src);
    command.stdout(Stdio::pipes().as_raw_fd());
    command.stderr(Stdio::pipes().as_raw_fd());
    let output = match command.spawn() {
        Ok(o) => o,
        Err(_) => return 1,
    };
    let mut time_start = time::Instant::now();
    io::copy(&mut output.stdin(), &mut io::stdout()).unwrap();
    let _ = output.wait();
    let time_elapsed = time_start.elapsed().as_secs_f64();
    let rss_before = get_rss();
    let status_code = output.wait()?.code();
    if status_code != 0 {
        error!("Compilation failed with status code: {}", status_code);
        early_error(Error::from(status_code));
    }
    let rss_after = get_rss();
    info!(
        "Compiled source in {} seconds, RSS before: {}, RSS after: {}, Resident set size delta: {}",
        time_elapsed, rss_before, rss_after, (rss_after - rss_before) as u64
    );
    status_code
}

#[sync_lazy::SyncLazy]
fn setup_logger() -> log::Logger {
    let mut builder = log::Builder::new();
    builder.filter(None, LevelFilter::Info);
    builder.format_module_path(false);
    builder.target("error" => log::Target::Stderr).init().unwrap();
    builder.build()
}
```']

