    }
}

async fn run() {
    let api_client = ApiClient::new().await;

    let tasks = vec![
        task::spawn(api_client.request("...").then(|res| { /* handle response */ })),
        task::spawn(api_client.request("...").then(|res| { /* handle response */ })),
        // ... more tasks
    ];

    let mut runtime = Runtime::new().expect("Failed to create tokio runtime");

    while tasks.len() > 0 && runtime.block_on(tasks.len()).await > 0 {
        runtime.execute_blocking(move || {
            tasks.drain(..MAX_CONCURRENT_REQUESTS)
                .map(|task| task.poll())
                .filter_map(|poll| poll.as_mut().then(|result| result.map(|res| tasks.push(async move { /* handle response */ }))))
                .collect::<Vec<_>>()
        })
        .await;
    }
}

fn main() {
