// ThreadSafeQueue is a thread-safe queue for managing the producer-consumer pattern
template <typename T>
class ThreadSafeQueue {
public:
    void enqueue(const T& item) {
        std::unique_lock<std::mutex> lock(m_);
        data_.push(item);
        condition_.notify_one();
    }

    T dequeue() {
        std::unique_lock<std::mutex> lock(m_);
        if (data_.empty()) {
            condition_.wait(lock, [this] { return !data_.empty(); });
        }
        T item = data_.front();
        data_.pop();
        return item;
    }

private:
    std::queue<T> data_;
    std::mutex m_;
    std::condition_variable condition_;
};

// The main application logic resides here, implementing the key requirements as described.
```

