#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* copy_with_suffix(const char* input, const char* suffix) {
    size_t length = strlen(input);
    size_t new_length = length + strlen(suffix);
    char *new_str = (char*)malloc(new_length + 1); // +1 for null terminator
    strcpy(new_str, input);
    strcat(new_str, suffix);
    return new_str;
}
