#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <libgen.h>
#include <dirent.h>
#include <limits.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <semaphore.h>

// Max concurrent threads based on system capabilities
#define THREAD_POOL_SIZE 4 + sysconf(_SC_NPROCESSORS_ONLINE) / 2

// Error codes
enum {
    SUCCESS = 0,
    INVALID_INPUT_DIR = 1,
    NO_IMAGE_FILES = 2,
    CONVERSION_ERROR = 3,
    SYSTEM_RESOURCE_LIMITATION = 4,
    DISK_SPACE_LIMITATION = 5
};

// Custom compare function for qsort
int compare(const void *a, const void *b) {
    return strcmp(*(char **)a, *(char **)b);
}

// Thread data structure
typedef struct thread_data {
    char *inputFile;
    char *outputPath;
} ThreadData;

// Error function to print error message and exit with appropriate code
void error(const char *msg, int errCode) {
    perror(msg);
    fprintf(stderr, ": %s\n", strerror(errCode));
    exit(errCode);
}

// Function to check if a directory exists
int dirExists(char *path) {
    struct stat st;
    return (stat(path, &st) == 0 && S_ISDIR(st.st_mode));
}

// Function to get supported image formats
char **getSupportedFormats() {
    static char *formats[] = {"*.jpg", "*png"};
    return formats;
}

// Function to convert a single image file to PDF using external command
int convertImageToPDF(char *inputFile, char *outputPath) {
    char cmd[1024];
    snprintf(cmd, sizeof(cmd), "%s %s -o %s", "convert", inputFile, outputPath);
    pid_t pid = fork();

    if (pid == -1)
        return CONVERSION_ERROR;

    if (!pid) {
        execl("/usr/bin/convert", "convert", inputFile, "-o", outputPath, NULL);
        error("Error executing 'convert' command", CONVERSION_ERROR);
    }

    // Wait for the child process to finish
    int status;
    if (waitpid(pid, &status, 0) == -1)
        return CONVERSION_ERROR;

    if (!WIFEXITED(status)) {
        error("Child process did not exit cleanly", CONVERSION_ERROR);
    }

    return WEXITSTATUS(status);
}

// Function to convert an image sequence to PDFs using a thread pool
int convertImageSequenceToPDFs(char *inputDir, char *outputDir) {
    if (!dirExists(inputDir))
        error("Input directory does not exist", INVALID_INPUT_DIR);

    DIR *dp = opendir(inputDir);
    struct dirent *de;
    int numFiles = 0, convertedFiles = 0;

    // Find all supported image files in the input directory
    while ((de = readdir(dp)) != NULL) {
        char *fileExtension = strchr(de->d_name, '.');
        if (fileExtension && fileExtension[1] == '\0') continue; // Not a valid filename

        for (size_t i = 0; getSupportedFormats()[i]; ++i) {
            if (!strcasestr(de->d_name, getSupportedFormats()[i])) continue;

            numFiles++;
            break;
        }
    }
    closedir(dp);

    if (numFiles == 0) error("No supported image files found in the input directory", NO_IMAGE_FILES);

    // Create temporary storage for intermediate files
    char tempDir[PATH_MAX];
    snprintf(tempDir, sizeof(tempDir), "%s/tmp", inputDir);
    if (mkdir(tempDir, 0755) != 0 && errno != EEXIST) error("Unable to create temporary storage", SYSTEM_RESOURCE_LIMITATION);

    // Sort image files by name for easier processing
    struct dirent *files[numFiles];
    int idx = 0;
    dp = opendir(inputDir);

    while ((de = readdir(dp)) != NULL) {
        char *fileExtension = strchr(de->d_name, '.');
        if (fileExtension && fileExtension[1] == '\0') continue; // Not a valid filename

        for (size_t i = 0; getSupportedFormats()[i]; ++i) {
            if (!strcasestr(de->d_name, getSupportedFormats()[i])) continue;

            files[idx++] = de;
            break;
        }
    }
    closedir(dp);

    qsort(files, idx, sizeof(struct dirent *), compare);

    // Create a thread pool and process images concurrently
    pthread_t threadPool[THREAD_POOL_SIZE];
    sem_t semaphore;
    int numThreads = 0, totalConvertedFiles = 0;
    ThreadData *data;

    if (sem_init(&semaphore, 0, THREAD_POOL_SIZE) != 0) error("Unable to initialize semaphore", SYSTEM_RESOURCE_LIMITATION);

    for (int i = 0; i < idx; ++i) {
        data = malloc(sizeof(ThreadData));
        data->inputFile = strdup(files[i]->d_name);
        data->outputPath = strcat(strdup(tempDir), "/");
        strcat(data->outputPath, data->inputFile);
        strcat(data->outputPath, ".pdf");
        pthread_create(&threadPool[numThreads++], NULL, convertPDFThread, data);
    }

    // Wait for all threads to finish
    int status;
    for (int i = 0; i < numThreads; ++i) {
        if (pthread_join(threadPool[i], &status)) error("Error joining thread", SYSTEM_RESOURCE_LIMITATION);
        totalConvertedFiles += WIFEXITED(status) && WEXITSTATUS(status) == SUCCESS ? 1 : 0;
    }

    sem_destroy(&semaphore);

    // Move converted PDFs from temporary storage to the output directory
    dp = opendir(tempDir);
    DIR *outputDP = opendir(outputDir);

    if (!outputDP) error("Output directory does not exist", INVALID_INPUT_DIR);

    struct dirent *td, *od;
    while ((td = readdir(dp)) != NULL && (od = readdir(outputDP))) {
        if (strcmp(td->d_name, od->d_name) != 0) continue;

        char tPath[PATH_MAX];
        char oPath[PATH_MAX];
        snprintf(tPath, sizeof(tPath), "%s/%s", tempDir, td->d_name);
        snprintf(oPath, sizeof(oPath), "%s/%s", outputDir, od->d_name);

        if (rename(tPath, oPath) != 0 && errno != EEXIST) error("Unable to move converted PDF from temporary storage", SYSTEM_RESOURCE_LIMITATION);
    }
    closedir(dp);
    closedir(outputDP);

    // Clean up temporary files that were not successfully converted
    dp = opendir(tempDir);
    while ((de = readdir(dp)) != NULL) {
        char tPath[PATH_MAX];
        snprintf(tPath, sizeof(tPath), "%s/%s", tempDir, de->d_name);

        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;

        remove(tPath);
    }
    closedir(dp);

    free(files);

    // Return error code if any conversions failed
    return totalConvertedFiles < idx ? CONVERSION_ERROR : SUCCESS;
}

// Thread function to convert a single image file to PDF
void *convertPDFThread(void *arg) {
    ThreadData *data = (ThreadData *) arg;

    sem_wait(&semaphore); // Wait for an available thread slot

    char inputFile[PATH_MAX];
    strcpy(inputFile, data->inputFile);
    char outputPath[PATH_MAX];
    strcpy(outputPath, data->outputPath);

    free(data->inputFile);
    free(data);

    int ret = convertImageToPDF(inputFile, outputPath);

    sem_post(&semaphore); // Signal that a thread slot is available again

    return (void *)ret;
}

// Main function
int main(int argc, char **argv) {
    if (argc != 3) error("Usage: convertImageSequenceToPDFs <input_dir> <output_dir>", INVALID_INPUT_DIR);

    int ret = convertImageSequenceToPDFs(argv[1], argv[2]);

    return ret;
}
