[' ```cpp
// Include necessary headers
#include <iostream>
#include <string>
#include <sstream>
#include <cstdlib> // For std::system()
#include <openssl/md5.h>

// Define MD5 method
std::string md5(const std::string& str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    char buffer[2 * MD5_DIGEST_LENGTH + 1];

    // Perform the hash operation
    auto content = reinterpret_cast<const unsigned char*>(str.c_str());
    auto len = static_cast<int>(str.length());
    unsigned int n;
    auto totalLen = len + (len % 64);
    auto newContent = new unsigned char[totalLen];
    std::copy(content, content + len, newContent);
    for (n = len * 8; n < totalLen * 8; n += 8) {
        newContent[n] = n / 512;
    }

    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, newContent, totalLen);
    MD5_Final(digest, &ctx);

    // Convert the binary digest to a hexadecimal string
    auto ostringstream = std::ostringstream();
    for (auto i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ostringstream << std::hex << std::setw(2) << std::setfill('0')
            << static_cast<int>(digest[i]);
    }

    // Free the allocated memory and return the result
    delete[] newContent;
    return ostringstream.str();
}
```

```java
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static String md5(String str) {
    try {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] messageDigest = digest.digest(str.getBytes(StandardCharsets.UTF_8));
        BigInteger number = new BigInteger(1, messageDigest);
        StringBuilder hashtext = new StringBuilder(number.toString(16));
        while (hashtext.length() < 32) {
            hashtext.insert(0, "0");
        }
        return hashtext.toString();
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}
```']

