```cpp
void initializeOctree(float featureSize, int numLeafNodes, std::vector<Node>& octree) {
    const float voxelSize = featureSize / (std::pow(2.0f, static_cast<float>(std::log2(numLeafNodes))));

    // Initialize root node with default values
    Node root;
    root.voxelSize = voxelSize;
    root.featureSize = featureSize;
    root.numLeafNodes = numLeafNodes;

    initializeNode(root, octree);
}

void initializeNode(Node& node, std::vector<Node>& nodes) {
    if (node.isLeaf()) {
        // Allocate leaf node data here
    } else {
        float childrenSize = node.voxelSize * static_cast<float>(std::pow(2.0f, 3));

        for (int i = 0; i < 8; ++i) {
            Node childNode;
            childNode.parent = &node;
            childNode.children = std::vector<Node>();

            float offsetX = node.voxelSize * static_cast<float>(i % 2);
            float offsetY = node.voxelSize * static_cast<float>((i / 2) % 2);
            float offsetZ = node.voxelSize * static_cast<float>((i / 4) % 2);

            childNode.position[0] = node.position[0] + offsetX;
            childNode.position[1] = node.position[1] + offsetY;
            childNode.position[2] = node.position[2] + offsetZ;

            nodes.push_back(childNode);
            initializeNode(childNode, nodes);
        }
    }
}
