class ThreadPool {
    private $workers;
    private $queue;

    public function __construct($numWorkers = null) {
        $this->queue = new SplQueue();
        $this->workers = [];

        if ($numWorkers !== null) {
            for ($i = 0; $i < $numWorkers; $i++) {
                $this->workers[] = new Thread($this->processNextTask);
            }
        }
    }

    public function execute(Runnable $task) {
        $this->queue->enqueue($task);
        if (empty($this->workers)) {
            for ($i = 0; $i < 10; $i++) {
                $this->workers[] = new Thread($this->processNextTask);
            }
        }
    }

    private function processNextTask() {
        while (($task = $this->queue->dequeue()) !== null) {
            try {
                $task->run();
            } catch (Exception $e) {
                // Handle exception and possibly retry or log the error
            }
        }
    }
}

