**Memory pool allocator example:**

```c
#include <stdlib.h>

struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

void* memory_pool_alloc(struct MemoryPool* pool) {
    if (pool->used < pool->capacity) {
        // Return the next available buffer from the pool
        void* result = pool->buffer + pool->used;
        pool->used++;
        return result;
    } else {
        // Allocate new memory when the pool is full
        void* result = malloc(pool->capacity);
        if (result == NULL) {
            // Handle out-of-memory error here
        }
        memset(result, 0, pool->capacity);
        pool->buffer = result;
        pool->used++;
        return result;
    }
}
```']

