        private readonly ITransformer[] _transformers;
        private readonly IDatabaseLoader _databaseLoader;

        // Dependency Injection constructor
        public TransformationManager(IDataProcessor[] dataProcessors, ITransformer[] transformers, IDatabaseLoader databaseLoader)
        {
            _dataProcessors = dataProcessors;
            _transformers = transformers;
            _databaseLoader = databaseLoader;
        }

        public void ProcessDataStream(IEnumerable<Message> messages)
        {
            Parallel.ForEach(messages, message =>
            {
                // Iterate through data processors to handle different sources and apply transformations in-between
                foreach (var processor in _dataProcessors)
