#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <lru_cache.h>
#include <openssl/aes.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/sysinfo.h>
#include <libevent/event.h>
#include <json-c/json.h>
#include "logging_service.h"
#include "distributed_db.h"
#include "load_balancer.h"

typedef struct {
    char *input;
    size_t limit;
    const char *suffix;
} params;

void* allocate_string(void *arg) {
    params *p = arg;
    char *result;
    size_t len = strlen(p->input) + strlen(p->suffix);

    if (len > p->limit) {
        log_event("String allocation failed: string too long");
        return NULL;
    }

    result = malloc(len + 1);
    strcpy(result, p->input);
    strcat(result, p->suffix);

    lru_cache_put("string", result, len + 1, NULL);

    return result;
}

char* safe_allocate_string(const char *input, size_t limit, const char *suffix) {
    params *p = malloc(sizeof(params));
    p->input = strdup(input);
    p->limit = limit;
    p->suffix = suffix;

    void *thread_result = event_new_thread(allocate_string, p);
    if (thread_result == NULL) {
        log_event("String allocation failed: thread creation error");
        free(p->input);
        free(p);
        return NULL;
    }

    char *result = (char*)thread_result;
    if (!result) {
        log_event("String allocation failed: allocation error");
        free(p->input);
        free(p);
        return NULL;
    }

    // Asynchronously record the allocation attempt
    record_allocation_attempt();

    return result;
}

