// Thread-safe unique identifier generation using atomic operations
atomic_t next_id = ATOMIC_INIT(0);

void append_unique_id(char* buffer) {
    size_t len = strlen(buffer);
    if (len >= MAX_BUFFER_LENGTH) {
        // Error handling logic goes here
    }
    char id[ID_LENGTH];
    sprintf(id, "%ld", atomic_fetch_add(&next_id, 1));
    strncat(buffer, id, ID_LENGTH);
}

typedef struct {
