```javascript
const { Buffer } = require('buffer');

function copyBuffer(chunks, start, end) {
  const result = Buffer.allocUnsafe(end - start);
  chunks.forEach((chunk, i) => {
    if (i >= start && i < end)
      result.writeBuffer(chunk, 0, chunk.length);
  });
  return result;
}
```']

