const axios = require('axios');
const { promisify } = require('util');
const fs = require('fs');
const readline = require('readline');
const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');

const dbConnection = require('./db-connection'); // Database connection module
const BookDefinition = require('./book-definition'); // Book definition class

// Customizable regular expression for matching book names
const bookRegex = /(Joshua|Exodus|Genesis|Leviticus|Numbers|Deuteronomy|Judges|Ruth|1\s+Samuel|2\s+Samuel|1\s+Kings|2\s+Kings|1\s+Chronicles|2\s+Chronicles|Ezra|Nehemiah|Esther)/gi;

// Asynchronous function to read a large text file line by line
const readLargeText = promisify(fs.createReadStream).bind(fs.createReadStream);

// Function to count occurrences of book names in a text input
async function countBookOccurrences(text) {
  let matches = [];
  const rl = readline.createInterface({
    input: readLargeText(__dirname + '/large-text-input.txt'), // Replace with the path to your large text file
    console: process.stdout,
    terminal: false
  });

  for await (const line of rl) {
    const bookMatches = line.match(bookRegex);
    if (bookMatches) matches = matches.concat(bookMatches);
  }

  // Remove duplicates and count occurrences
  const uniqueBooks = [...new Set(matches)];
  const counts = uniqueBooks.reduce((acc, book) => {
    acc[book] = (acc[book] || 0) + 1;
    return acc;
  }, {});

  // Fetch definitions for each book
  const promises = Object.keys(counts).map(async book => ({ book, definition: await BookDefinition.getDefinition(dbConnection, book) }));
  const results = await Promise.all(promises);

  return results.reduce((acc, { book, definition }) => {
    acc[book] = { count: counts[book], definition };
    return acc;
  }, {});
}

// Database connection class for managing connections efficiently
