@RestController
public class EncryptionController {
    private final EncryptionService encryptionService;
    private final RateLimiter rateLimiter; // Implement custom RateLimiter interface or use Spring's rate limiting support

    @Autowired
    public EncryptionController(EncryptionService encryptionService, RateLimiter rateLimiter) {
        this.encryptionService = encryptionService;
        this.rateLimiter = rateLimiter;
    }

    @PostMapping("/deserialize")
    public ResponseEntity<String> deserialize(@RequestBody byte[] data) {
        if (!rateLimiter.allow()) {
            return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body("Rate limit exceeded");
        }

        try {
            byte[] decryptedData = encryptionService.decrypt(data);
            String result = new String(decryptedData, StandardCharsets.UTF_8);
            return ResponseEntity.ok().body(result);
        } catch (Exception e) {
            return ResponseEntity.badRequest().body("Error during deserialization: " + e.getMessage());
        }
    }
}
