        if cpu_utilization > self.CPU_UTILIZATION_THRESHOLD:
            v1.create_pod(namespace='default', body={...})  # Create a new processing instance
        elif cpu_utilization < self.CPU_UTILIZATION_MIN_THRESHOLD:
            v1.delete_namespaced_pod(name, 'default', body={...})  # Delete an unused processing instance

# Custom Beam transforms for reading and writing files
class ReadBatchFiles(beam.DoFn):
    def process(self, element):
        yield element, os.path.basename(element)

class WriteResults(beam.DoFn):
    def process(self, element):
        key, value = element
        yield (key, str(value))

def run_pipeline(options):
    pipeline = beam.Pipeline(options=options)
    (
        pipeline
        | 'Read data from PubSub' >> ReadFromText(subscription)
        | 'Split files' >> WithKeys(ReadBatchFiles())
        | 'Process files' >> Map(process_file)
        | 'Write results' >> WriteToText('results')
    )
    pipeline.run()

if __name__ == "__main__":
    options = PipelineOptions(
        project='your_project',
        region=region,
        job_name='batch-file-processor',
        staging_location='gs://your-bucket/staging',
        temp_location='gs://your-bucket/temp'
    )
