#include <openssl/pem.h>
#include <openssl/rsa.h>
#include <fstream>
#include <iostream>

std::string fetch_certificate(const std::string& certificateLocation) {
    std::ifstream inputFile(certificateLocation);
    if (!inputFile.is_open()) {
        std::cerr << "Error opening certificate file." << std::endl;
        return "";
    }

    BIO* bio = BIO_new_mem_buf(nullptr, M2_MODE_WWRITE | M2_LE0);
    PEM_write_PrivateKey(bio, RSA_key, nullptr, nullptr, 0, nullptr, nullptr);
    PEM_write_bio_PrivateKey(bio, RSA_key, NULL, NULL, 0, NULL, NULL);

    unsigned char* keyData = NULL;
    size_t keyDataLen = BIO_get_mem_data(bio, &keyData);

    std::string certificatePem;
    for (size_t i = 0; i < keyDataLen; ++i) {
        char c = static_cast<char>(keyData[i]);
        if (c == '\n') {
            c = ' ';
        }
        certificatePem += c;
    }

    BIO_free_all(bio);

    return certificatePem;
}
