    // Initialize strategic actions, configure their priority levels and callback functions

    ActionManager actionManager;

    std::thread actionThread(ActionManager::run);

    while (true) {
        // Execute game logic here, dequeue and enqueue strategic actions as needed
    }

    actionThread.join();
    return 0;
}
