        var queries = CreateSortedQueryList(queryParams);
        using var semaphore = new SemaphoreSlim(queries.Count, queries.Count);

        Func<IEnumerable<Tuple<string, DbParameter[], Action<IDbDataParameter, Exception>>>, Task BatchExecuteAsync => async queryList =>
