JavaScript Reduce function:

```javascript
function asyncReduce(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    const reducer = (accumulator, currentNumber) => {
      return new Promise((innerResolve, innerReject) => {
        callback(accumulator, currentNumber).then(result => {
          innerResolve(result);
        }).catch(error => {
          innerReject(error);
        });
        accumulator = result;
      });
    };

    const asyncIterable = arr[Symbol.asyncIterator] || function () {
      return {
        next: function () {
          return {
            value: arr.shift(),
            done: !arr.length
          };
        }
      };
    };

    const asyncReducerFn = asyncGenerator(asyncIterable, reducer);
    asyncReducerFn.next().then(({value, done}) => {
      if (!done) {
        asyncReducerFn.next().then(resolve).catch(reject);
      } else {
        resolve(accumulator);
      }
    }).catch(reject);
  });
}
```"]

