    private static final Duration CACHE_TTL = Duration.ofMinutes(5);
    private static final double SLOPE = 0.02; // Adjust based on historical data and traffic patterns

    public static void main(String[] args) {
        SpringApplication.run(RequestThrottlingService.class, args);

        StreamsBuilder builder = new StreamsBuilder();

