                .stream(/* Input topic configuration */)
                .transformValues(() -> new RateLimitingTransformer())
                .to("output-topic")
                .build();

        streams.start();
    }

    public static class RateLimitingTransformer implements Transformer<String, String> {
        private final Cache<Long, Integer> rateLimitCache = CacheBuilder.newBuilder()
                .maximumSizePerKey(1) // Max one request per IP per second
                .expireAfterAccess(CACHE_TTL)
                .build();

        @Override
        public Supplier<PublishableHandler<String>> transformer() {
            return () -> new ForwardingPublishableHandler<>(new HandlerWithResponse<String>() {
                private final SimpleRegression regression = new SimpleRegression();

                @Override
                public void apply(String input, Handler<Publishable<String>> handler) {
                    long currentTime = System.currentTimeMillis();
                    int requestsPerSecond = (int)(1000.0 / TimeUnit.MILLISECONDS.toSeconds(currentTime - regression.getLastTime()));
                    double predictedLoad = regression.getSlope() * currentTime + regression.getIntercept();
                    int rateLimit = (int)(predictedLoad * SLOPE); // Adjust based on predefined thresholds and real-time load

                    if (rateLimit < requestsPerSecond) {
                        rateLimitCache.put(input, 1);
                        handler.handle(input);
                    } else {
                        log.warn("Exceeded RPS limit for IP {}", input);
                    }
                }
            });
        }
    }
}
```

