template<typename T>
class Cache {
public:
    T get(const std::string& key, const std::function<T()>& loadFunction) {
        auto it = cache.find(key);
        if (it != cache.end()) {
            // Cache hit
            return it->second;
        } else {
            // Cache miss, load data and store in the cache
            T data = loadFunction();
