manage_crc_indications_status manage_crc_indications(size_t N, NFAPI_CRC_INDICATION_PDU_T **data, int *error) {
    if (N <= 0) {
        *error = MANAGE_CRC_INDICATIONS_INVALID_N;
        return MANAGE_CRC_INDICATIONS_INVALID_N;
    }

    NFAPI_CRC_INDICATION_PDU_T **local_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * N);
    if (!local_data) {
        *error = MANAGE_CRC_INDICATIONS_MEMORY_FAILURE;
        return MANAGE_CRC_INDICATIONS_MEMORY_FAILURE;
    }

    size_t i;
    for (i = 0; i < N; ++i) {
        local_data[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!local_data[i]) {
            *error = MANAGE_CRC_INDICATIONS_MEMORY_FAILURE;
            return MANAGE_CRC_INDICATIONS_MEMORY_FAILURE;
        }
    }

    pthread_mutex_lock(&data_mutex);
    *data = get_data_array();
    if (*data) {
        free(*data);
    }
    set_data_array(local_data);
    pthread_mutex_unlock(&data_mutex);

    return MANAGE_CRC_INDICATIONS_SUCCESS;
}

void init_manage_crc_indications() {
    pthread_mutex_init(&data_mutex, NULL);
    pthread_key_create(&data_array, data_array_destructor);

