```cpp
#include <functional>
#include <future>
#include <queue>
#include <thread>

template<typename T>
class TransactionProcessor {
public:
    void processTransaction(T transaction) {
        // Process the transaction here
    }
};

class RTA {
private:
    std::priority_queue<std::future<void>> transactions;
    std::vector<std::unique_ptr<TransactionProcessor>> processors;
public:
    void addTransaction(std::function<T()> transactionFetcher) {
        transactions.push([transactionFetcher]() mutable {
            auto t = transactionFetcher();
            processTransaction(t);
        });
    }

    void start() {
        for (auto& processor : processors) {
            std::thread{std::move(processor), std::ref(transactions)}.detach();
        }
    }
};
```

