public:
    RetryStrategy(int maxRetries, int retryDelay)
        : maxRetries_(maxRetries), retryDelay_(retryDelay) {}

    bool shouldRetry() const override {
        if (attempts_ < maxRetries_) {
            attempts_++;
            return true;
        }
        return false;
    }

    void handleError(const Error& error) override {
        if (!shouldRetry()) {
            // Log the persistent error and execute fallback mechanism
        } else {
            std::this_thread::sleep_for(std::chrono::milliseconds(retryDelay_));
            attempts_ = 0;
        }
    }
private:
