// Thread-safe dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} ThreadSafeArray;

void InitializeThreadSafeArray(ThreadSafeArray* array, size_t initial_size) {
    if (initial_size > 10000) {
        fprintf(stderr, "Initial size cannot exceed 10000\n");
        exit(EXIT_FAILURE);
    }

    array->data = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory for the array\n");
        exit(EXIT_FAILURE);
    }

    array->size = initial_size;
    array->capacity = initial_size;
    pthread_mutex_init(&array->mutex, NULL);
}

void ResizeThreadSafeArray(ThreadSafeArray* array, size_t new_capacity) {
    if (new_capacity > 10000 || new_capacity <= array->size) return;

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        fprintf(stderr, "Failed to resize array\n");
        exit(EXIT_FAILURE);
    }

    array->data = temp;
    array->capacity = new_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* GetThreadSafeArrayElement(const ThreadSafeArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    NFAPI_CRC_INDICATION_PDU_T* element = &array->data[index];
