3. BatchUploadImages.py

```python
import os
import time
from google.cloud import storage
from apibundle import BatchProcessingApiClient

def batch_upload_images(image_files, metadata):
    bucket_name = "my-bucket"
    client = storage.Client()
    blob_prefix = "processed_images/"
    api_client = BatchProcessingApiClient()

    failures = []
    processed_blobs = []
    upload_chunk_size = 5

    for i in range(0, len(image_files), upload_chunk_size):
        chunk_end = min((i + upload_chunk_size), len(image_files))
        chunk_images = image_files[i:chunk_end]
        chunk_metadata = metadata[i:chunk_end]

        try:
            blobs = []
            statuses = []

            for file, meta in zip(chunk_images, chunk_metadata):
                blob_name = f"{blob_prefix}{os.path.basename(file)}"
                blob = client.create_bucket(bucket_name).create_blob(blob_name)
                blob.upload_from_filename(file)
                blobs.append(blob)

            results = api_client.batchProcessImages(blobs, meta_data=metadata)

            for result in results:
                processed_blobs.append((result['imageBlob'], result['metaData']))
                statuses.append(result['status'])

        except Exception as e:
            failures.extend([file for file in chunk_images if not any(failure == file for failure in failures)])
            print(f"Error uploading images: {e}")
            time.sleep(5)
            continue

    return processed_blobs, failures
```']

