typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} list_node_t;

struct list_meta {
    size_t capacity;
    size_t num_elements;
    list_node_t **nodes;
    pthread_mutex_t lock;
};

// Custom memory pool for efficient allocation/deallocation
typedef struct mem_pool {
    void *memory;
    size_t allocated;
    size_t capacity;
} mem_pool_t;

void list_init(struct list_meta *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->num_elements = 0;
    list->nodes = mmap(NULL, sizeof(list_node_t *) * initial_capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list->nodes == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    list->lock = PTHREAD_MUTEX_INITIALIZER;
}

void *mem_pool_alloc(mem_pool_t *pool, size_t size) {
    if (pool->capacity <= pool->allocated + size) {
        void *new_memory = realloc(pool->memory, pool->capacity + size);
        if (!new_memory) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        pool->capacity += size;
    }
    return pool->memory + pool->allocated;
}

void mem_pool_free(mem_pool_t *pool, void *ptr) {
    if (ptr >= pool->memory && ptr < pool->memory + pool->capacity) {
        pool->allocated += (size_t)(ptr - pool->memory);
    }
}

