double transaction_filter(Transaction transactions[], int num_transactions, const char* config_file) {
    // Initialize the transaction filter manager with the given configuration file
    init_transaction_filter_manager(config_file);

    double max_weighted_sum = 0.0;
    Transaction* max_transaction = NULL;

    for (int i = 0; i < num_transactions; ++i) {
        // Apply the filter criteria on each transaction
        if (transaction_meets_criteria(transactions[i])) {
            double weighted_sum = calculate_weighted_sum(transactions[i]);

            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
