class Logger : public ILogger {
private:
    NodeConfig config;
    std::unordered_map<std::string, std::vector<ISink*>> sinks;

public:
    Logger(const NodeConfig& config) : config(config) {
        // Initialize sinks based on configuration.
    }

    void log(const LogEntry& entry) override {
        auto it = sinks.find(entry.tag);
        if (it != sinks.end()) {
            for (auto sink : it->second) {
                sink->process(entry);
            }
        }
    }
};

