```javascript
const express = require('express');
const axios = require('axios');
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());

// Endpoint to receive user activity streams
app.post('/activity-stream', async (req, res) => {
  const event = req.body;
  const normalizedEvent = normalizeEvent(event); // Implement this function for data consistency and integrity

  const analyticsServices = [
    'https://analytics-service1.com',
    'https://analytics-service2.com',
    'https://analytics-service3.com'
  ];

  try {
    for (let url of analyticsServices) {
      await sendAnalytics(normalizedEvent, url); // Implement this function to ensure low-latency and efficient resource utilization
    }
  } catch (error) {
    console.error('Error sending analytics:', error);
  }

  res.status(200).send();
});

// Function to send analytics data to the appropriate service
async function sendAnalytics(event, url) {
  try {
    const response = await axios.post(url, event);
    if (response.status !== 200) {
      throw new Error('Error sending analytics');
    }
  } catch (error) {
    console.error(`Error sending analytics to ${url}:`, error);
  }
}
```

