void selectAttack() {
    static std::atomic<uint64_t> last_time = 0;
    static uint32_t current_attack = 0;
    static std::atomic<uint64_t> current_time = std::chrono::high_resolution_clock::now().time_since_epoch().count();
    constexpr uint64_t cooldown_period_ns = 9 * 1e9; // 9 seconds in nanoseconds

