2. C# Method for Creating Parameterized SQL Commands (using System.Data.SqlClient and System.Collections.Generic)

```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public class DatabaseHelper
{
    private readonly string _connectionString;

    public DatabaseHelper(string connectionString) => _connectionString = connectionString;

    public IDataReader ExecuteParameterizedCommand(string commandText, List<object> parameters)
    {
        using var connection = new SqlConnection(_connectionString);
        connection.Open();
        var command = new SqlCommand(commandText, connection);
        command.Parameters.AddRange(parameters.Select((p, i) => new SqlParameter("@p" + i.ToString(), p)).ToArray());
        return command.ExecuteReader();
    }
}
```

