4. **String Processing Function**: Implement a thread-safe function for appending unique identifiers to user-provided strings:

```c
#include <time.h>
#include <openssl/sha.h> // Assuming OpenSSL is being used

char* addUniqueIdentifier(const char* input, size_t maxLength) {
    SHA256_CTX ctx;
    unsigned char digest[SHA256_DIGEST_LENGTH];

    // Hash the filename extension (if provided) and timestamp
    // Add more relevant data to the hash as needed for uniqueness

    SHA256_Init(&ctx);
    SHA256_Update(&ctx, input, strlen(input));
    SHA256_Final(digest, &ctx);

    size_t extensionLength = 0;
    char* extension = strrchr(input, '.');
    if (extension) {
        extensionLength = strlen(extension);
    }

    // Truncate the hash and append it to the input string
    char uniqueIdentifier[SHA256_DIGEST_LENGTH * 2 + 1];
    for (int i = 0; i < SHA256_DIGEST_LENGTH && i < sizeof(uniqueIdentifier) - extensionLength - 1; ++i) {
        sprintf(&uniqueIdentifier[i], "%02x", digest[i]);
    }
    uniqueIdentifier[SHA256_DIGEST_LENGTH * 2] = '\0';

    if (extension && strlen(input + strlen(input) - extensionLength) + SHA256_DIGEST_LENGTH * 2 + 1 <= maxLength) {
        strcat(input, uniqueIdentifier);
        return input;
    } else {
        // Return error or log an error message and provide a truncated version of the input string
        char errorMessage[strlen(input) + 50];
        sprintf(errorMessage, "String length exceeded maximum limit of %ld characters", maxLength);
        // Log the error message using a logging library like log4c or system logs
        return strdup(input + strlen(input) - extensionLength);
    }
}
```

