namespace DataSecurityModule
{
    public class DataSecurityModule : IDataSecurityModule
    {
        private static readonly ILog _logger = LogManager.GetLogger(typeof(DataSecurityModule));
        private readonly IKeyStore _keyStore;
        private readonly ILoggingFramework _loggingFramework;
        private readonly object _lockObject = new Object();
        private readonly Dictionary<string, Aes> _keyCache = new Dictionary<string, Aes>();
        private readonly TimeSpan _cacheExpiration = TimeSpan.FromMinutes(5);

        public DataSecurityModule(IKeyStore keyStore, ILoggingFramework loggingFramework)
        {
            _keyStore = keyStore;
            _loggingFramework = loggingFramework;
        }

        private Aes GetOrCreateAesKey(string algorithm)
        {
            lock (_lockObject)
            {
                if (!_keyCache.TryGetValue(algorithm, out var aes))
                {
                    _logger.Info($"Creating new key for {algorithm}");
                    aes = KeyCreationHelper.CreateAesKey(algorithm);
                    _keyCache[algorithm] = aes;
                }

                if (DateTime.Now > aes.Key.Expiration)
                {
                    _logger.Info($"Rotating key for {algorithm}");
                    aes = KeyCreationHelper.CreateAesKey(algorithm);
                    _keyCache[algorithm] = aes;
                }

                return aes;
            }
        }

        public byte[] Encrypt(string algorithm, byte[] data)
        {
            using var aes = GetOrCreateAesKey(algorithm);
            var encryptedData = AESEncryptionHelper.Encrypt(aes, data);
            LogEncryptionEvent(algorithm, "Encrypt", true, encryptedData.Length);
            return encryptedData;
        }

        public byte[] Decrypt(string algorithm, byte[] encryptedData)
        {
            using var aes = GetOrCreateAesKey(algorithm);
            var decryptedData = AESEncryptionHelper.Decrypt(aes, encryptedData);
            LogEncryptionEvent(algorithm, "Decrypt", true, decryptedData.Length);
            return decryptedData;
        }

        private void LogEncryptionEvent(string algorithm, string operationType, bool success, int dataLength = 0)
        {
            try
            {
                _loggingFramework.Log(new EncryptionLogEntry
                {
                    Timestamp = DateTime.Now,
                    OperationType = operationType,
                    Success = success,
                    Algorithm = algorithm,
                    DataLength = dataLength
                });
            }
            catch (Exception ex)
            {
                _logger.Error("Failed to log encryption event.", ex);
            }
        }
    }
}
```

