2. **C (AES-256-CBC Initialization and Cleanup)**

```c
#include <openssl/aes.h>
#include <openssl/sha.h>
#include <string.h>

typedef AES_KEY AESContext;

AESContext* aes_init(const char* password) {
    // Initialize SHA-256 hash context
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));

    // Perform finalization and derive the key
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &sha256);

    // Initialize AES context with fixed IV and key lengths
    AESContext ctx;
    AES_set_encrypt_key(hash, 256, &ctx);

    return &ctx;
}

void aes_cleanup(AESContext* ctx) {
    // Disable the cipher when it is no longer needed
    AES_free_key((EVP_CIPHER *) ctx);
}
