      .then(res => res.json())
      .then(({content, version}) => {
        setContent(content);
        // Store the latest server version for conflict resolution
        localStorage.setItem('serverVersion', version);
      });
  }, [docId]);

  const handleSave = () => {
    fetch(`/api/documents/${docId}`, {
      method: 'PUT',
      headers: {'Content-Type': 'application/json'},
